mapper.select:
SELECT 
FROM im_channel c
WHERE c.del_flag = 0
 AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.topic LIKE CONCAT('%', #{keyword}, '%')) 
 AND c.guild_kind = #{guildKind} 
 AND c.guild_id = #{guildId} 
 AND c.status = #{status} 

     ORDER BY c.parent_id, c.position, c.id 
     ORDER BY c.id DESC 

LIMIT 100

SELECT 
FROM im_message m JOIN im_channel c ON c.id = m.conversation_id

     AND m.conversation_id = #{channelId} 
     AND m.sender_id = #{senderId} 
     AND m.content LIKE CONCAT('%', #{keyword}, '%') 
     AND m.status = #{status} 
     AND m.id < #{beforeId} 

ORDER BY m.id DESC
LIMIT #{limit}

SELECT r.id, r.reporter_member_id AS reporterMemberId, r.target_type AS targetType, r.target_id AS targetId,
       r.channel_id AS channelId, r.reason_code AS reasonCode, r.reason_text AS reasonText, r.status,
       r.audit_task_id AS auditTaskId, r.create_time AS createTime,
       m.sender_id AS senderId, m.content, m.status AS messageStatus, m.version AS messageVersion,
       c.name AS channelName, c.guild_kind AS guildKind, c.guild_id AS guildId
FROM im_channel_report r
LEFT JOIN im_message m ON r.target_type = 'MESSAGE' AND m.id = r.target_id
LEFT JOIN im_channel c ON c.id = r.channel_id

     AND r.status = #{status} 
     AND r.channel_id = #{channelId} 
     AND r.id < #{beforeId} 

ORDER BY r.id DESC
LIMIT #{limit}

SELECT id, guild_kind AS guildKind, guild_id AS guildId, target_member_id AS targetMemberId, action_type AS actionType,
       CASE WHEN status = 'ACTIVE' AND expires_at IS NOT NULL AND expires_at <= CURRENT_TIMESTAMP(3) THEN 'EXPIRED' ELSE status END AS status,
       version, scope_type AS scopeType, scope_id AS scopeId, reason_code AS reasonCode, reason_text AS reasonText,
       duration_sec AS durationSec, starts_at AS startsAt, expires_at AS expiresAt, operator_id AS operatorId,
       revoked_by AS revokedBy, revoke_reason AS revokeReason, revoked_at AS revokedAt
FROM im_moderation_action

     AND guild_kind = #{guildKind} 
     AND guild_id = #{guildId} 
     AND target_member_id = #{targetMemberId} 
     AND status = 'ACTIVE' AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP(3)) 
     AND status = #{status} 

ORDER BY id DESC
LIMIT #{limit}
